from __future__ import annotations
import copy
STATES={'welcome': ['start', 'recent', 'empty', 'import_settings', 'open_folder', 'workspace_trust'], 'agent_chat': ['empty', 'conversation', 'generating', 'context_attached', 'permission_request', 'clear_chat'], 'requirements': ['draft', 'generated', 'editing', 'validated', 'needs_revision', 'delete_spec'], 'design': ['overview', 'architecture', 'interfaces', 'data_model', 'alternatives', 'regenerate_design'], 'tasks': ['planned', 'running', 'completed', 'failed', 'optional_tasks', 'stop_task'], 'hooks': ['list', 'create', 'editing', 'disabled', 'run_history', 'delete_hook'], 'steering': ['files', 'always', 'file_match', 'manual', 'editing', 'delete_file'], 'mcp': ['servers', 'connected', 'disconnected', 'tools', 'configuration', 'add_server'], 'review': ['pending', 'diff', 'accepted', 'rejected', 'tests', 'revert_changes'], 'settings': ['general', 'appearance', 'editor', 'privacy', 'account', 'reset_settings']}
POPUPS={'open_folder', 'stop_task', 'workspace_trust', 'delete_hook', 'delete_spec', 'add_server', 'delete_file', 'regenerate_design', 'reset_settings', 'revert_changes', 'permission_request', 'clear_chat'}
CODE='export interface Note {\n  id: string;\n  title: string;\n  body: string;\n  updatedAt: number;\n}\n\nexport class NoteRepository {\n  private notes = new Map<string, Note>();\n\n  save(note: Note): void {\n    this.notes.set(note.id, note);\n  }\n\n  find(query: string): Note[] {\n    return [...this.notes.values()].filter(note =>\n      note.title.toLowerCase().includes(query.toLowerCase())\n    );\n  }\n}\n'
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'sample_index':sample_index,'project':'trail-notes','code':CODE,'files':['src','NoteRepository.ts','NotesScreen.tsx','tests','repository.test.ts','.kiro','specs/note-search','steering/product.md','hooks/check-tests.json'],'tasks':[{'title':t,'detail':d,'requirements':r} for t,d,r in [('Define Note and repository interfaces','Add typed storage operations and test fixtures','1.1, 1.2'),('Implement case-insensitive note search','Match titles without altering stored content','2.1, 2.2'),('Add search input and empty state','Keep search controls keyboard accessible','3.1'),('Write regression tests','Cover empty queries, casing, and missing results','2.2, 3.2')]],'hooks':[{'name':n,'event':e,'pattern':p} for n,e,p in [('check-tests','Agent file saved','src/**/*.ts'),('update-docs','Agent task completed','README.md'),('review-spec','Spec task completed','tasks.md')]],'steering':[{'name':n,'mode':m,'description':d} for n,m,d in [('product.md','always','Product goals and user expectations'),('tech.md','always','Stack and coding conventions'),('frontend.md','fileMatch','Accessibility and component guidance'),('release.md','manual','Release checklist and review steps')]],'servers':[{'name':n,'tools':t} for n,t in [('demo-docs',['search_docs','read_page']),('demo-project',['list_files','read_fixture'])]]}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d['state']=state;d['popup_visible']=state in POPUPS
 return d
